map "https://fhir.hl7.at/elga/cda2fhir/r4/StructureMap/at-cda-imaging-to-fhir-bundle" = "CdaImagingToFhirBundle"

//
// Mapping CDA2FHIR - Befund bildgebende Diagnostik (Diagnostic Imaging Report)
//
// Source: ELGA CDA "Befund bildgebende Diagnostik" https://art-decor.org/ad/#/elgabgd-/rules/templates/1.2.40.0.34.6.0.11.0.17/2024-11-07T13:09:21
//         ClinicalDocument/code/translation = 18748-4 (LOINC)
// Target: HL7 Europe Imaging Report R4 (https://hl7.eu/fhir/imaging/1.0.0-ballot/)
//
// This map holds all imaging-report specific mappings. The generic CDA header (recordTarget,
// author, custodian, legalAuthenticator, ...) and the section framework are reused from
// CdaToFhirBundle.4.map by extending its groups. The data types are reused from
// CdaToFhirTypes.4.map. See python-maps/documentation/imaging/ for the top-level mapping overview.
//
// Naming convention for groups: CdaImaging*ToFhir*
//
// ____________________________________ ConceptMaps ____________________________________

// Translation table: document status in CDA (sdtc:statusCode) -> DiagnosticReport.status
conceptmap "cda-imaging-sdtc-statuscode-2-fhir-diagnosticreport-status" {
  prefix s = "http://terminology.hl7.org/CodeSystem/v3-ActStatus"
  prefix t = "http://hl7.org/fhir/diagnostic-report-status"

  s:"active" == t:"preliminary"
  s:"nullified" == t:"entered-in-error"
}

// ____________________________________ Sources ____________________________________

uses "http://hl7.org/cda/stds/core/StructureDefinition/ClinicalDocument" alias ClinicalDocument as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Author" alias Author as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/AssignedAuthor" alias AssignedAuthor as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/AssignedEntity" alias AssignedEntity as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/AssociatedEntity" alias AssociatedEntity as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/CustodianOrganization" alias CustodianOrganization as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Section" alias Section as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/PatientRole" alias PatientRole as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/StructuredBody" alias StructuredBody as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Observation" alias CDAObservation as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Performer2" alias Performer as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Procedure" alias CDAProcedure as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Organizer" alias Organizer as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Participant1" alias Participant as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Act" alias Act as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Participant2" alias Participant2 as source

// ____________________________________ Targets ____________________________________

uses "http://hl7.org/fhir/4.3/StructureDefinition/Bundle" alias Bundle as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Composition" alias Composition as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Patient" alias Patient as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Person" alias Person as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Practitioner" alias Practitioner as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/PractitionerRole" alias PractitionerRole as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Organization" alias Organization as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Device" alias Device as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/DiagnosticReport" alias DiagnosticReport as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/ServiceRequest" alias ServiceRequest as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Observation" alias Observation as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/ImagingStudy" alias ImagingStudy as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Procedure" alias Procedure as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Condition" alias Condition as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/DocumentReference" alias DocumentReference as target

// ____________________________________ Imports ____________________________________

imports "http://hl7.at/fhir/HL7ATCoreProfiles/4.0.1/StructureMap/at-cda-to-fhir-types"


// _________________________ Document Level Template _________________________

// Entry point for the imaging report. Called from CdaToFhirBundle when
// ClinicalDocument/code/translation = 18748-4. The Composition and Patient base resources have already
// been created by the root group; here we create the DiagnosticReport and wire the
// base references, then delegate to the header and body groups.
group CdaImagingToFhirBundle(source cda: ClinicalDocument, target fhir_patient: Patient, target fhir_composition: Composition, target fhir_bundle: Bundle) {

  // Bundle.meta.profile
  cda ->
    fhir_bundle.meta as fhir_bundle_meta,
    fhir_bundle_meta.profile = 'http://hl7.eu/fhir/imaging/StructureDefinition/BundleReportEuImaging'
    "ImagingBundleProfile";

  cda ->
    // create the DiagnosticReport
    fhir_bundle.entry as fhir_bundle_entry_1,
    fhir_bundle_entry_1.resource = create('DiagnosticReport') as fhir_diagnosticReport,
    fhir_diagnosticReport.id = uuid() as fhir_diagnosticReport_id,
    fhir_bundle_entry_1.fullUrl = append('urn:uuid:', fhir_diagnosticReport_id),

    // retrieve Composition uuid
    fhir_composition.id as fhir_composition_id,

    // DiagnosticReport -> Composition (extension-DiagnosticReport.composition)
    fhir_diagnosticReport.extension as fhir_diagnosticReport_extension,
    fhir_diagnosticReport_extension.url = 'http://hl7.org/fhir/5.0/StructureDefinition/extension-DiagnosticReport.composition',
    fhir_diagnosticReport_extension.value = create('Reference') as fhir_diagnosticReport_composition_reference,
    fhir_diagnosticReport_composition_reference.reference = append('urn:uuid:', fhir_composition_id),
    fhir_diagnosticReport_composition_reference.type = 'Composition',

    // retrieve Patient uuid
    fhir_patient.id as fhir_patient_id,

    // DiagnosticReport -> Patient
    fhir_diagnosticReport.subject = create('Reference') as fhir_diagnosticReport_subject_reference,
    fhir_diagnosticReport_subject_reference.reference = append('urn:uuid:', fhir_patient_id),
    fhir_diagnosticReport_subject_reference.type = 'Patient'

    then {
      // map the CDA header
      cda then CdaImagingHeaderToFhirComposition(cda, fhir_composition, fhir_patient, fhir_bundle) "CdaImagingHeaderToFhirComposition";
      cda then CdaImagingHeaderToFhirDiagnosticReport(cda, fhir_diagnosticReport) "CdaImagingHeaderToFhirDiagnosticReport";
      cda then CdaImagingHeaderToFhir(cda, fhir_composition, fhir_patient, fhir_bundle, fhir_diagnosticReport) "CdaImagingHeaderToFhir";

      // map the CDA body
      // ClinicalDocument.component
      cda.component as cda_component then {
        // ClinicalDocument.component.structuredBody
        cda_component.structuredBody as cda_structuredBody
          then CdaImagingBodyToFhirComposition(cda, cda_structuredBody, fhir_composition, fhir_patient, fhir_diagnosticReport, fhir_bundle);
      };
    } "CdaImagingToFhirBundle";
}


// _________________________ Header Level Templates _________________________

// ClinicalDocument -> Composition (imaging report specific parts).
// Reuses the generic Composition header (title, status, effectiveTime, confidentiality,
// language, setId, versionNumber, ...) from CdaHeaderToFhirComposition.
group CdaImagingHeaderToFhirComposition(source cda: ClinicalDocument, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_bundle: Bundle) extends CdaHeaderToFhirComposition {
    // Composition.meta.profile
    cda ->
        fhir_composition.meta as fhir_composition_meta,
        fhir_composition_meta.profile = 'http://hl7.eu/fhir/imaging/StructureDefinition/CompositionEuImaging'
        "ImagingCompositionProfile";

    // ClinicalDocument/code -> Composition.type (same as DiagnosticReport.code)
    cda.code -> fhir_composition.type "ImagingCompositionType";

    // Composition.category (slice imaging-report, fixed value required by the profile)
    // The ELGA category (practiceSettingCode, e.g. Radiologie) is kept in addition.
    cda ->
        fhir_composition.category = create('CodeableConcept') as fhir_composition_category_report,
        fhir_composition_category_report.coding = create('Coding') as fhir_composition_category_report_coding,
        fhir_composition_category_report_coding.system = 'http://loinc.org',
        fhir_composition_category_report_coding.code = '85430-7'
        "ImagingCompositionCategoryReport";

    // Composition.category (slice imaging, fixed value required by the profile)
    cda ->
        fhir_composition.category = create('CodeableConcept') as fhir_composition_category_imaging,
        fhir_composition_category_imaging.coding = create('Coding') as fhir_composition_category_imaging_coding,
        fhir_composition_category_imaging_coding.system = 'http://hl7.eu/fhir/health-data-api/CodeSystem/eehrxf-document-priority-category-cs',
        fhir_composition_category_imaging_coding.code = 'Medical-Imaging'
        "ImagingCompositionCategoryImaging";
}

// ClinicalDocument -> DiagnosticReport.
group CdaImagingHeaderToFhirDiagnosticReport(source cda: ClinicalDocument, target fhir_diagnosticReport: DiagnosticReport) {
    // DiagnosticReport.meta.profile
    cda ->
        fhir_diagnosticReport.meta as fhir_diagnosticReport_meta,
        fhir_diagnosticReport_meta.profile = 'http://hl7.eu/fhir/imaging/StructureDefinition/DiagnosticReportEuImaging'
        "ImagingDiagnosticReportProfile";

    // ClinicalDocument/setId -> DiagnosticReport.identifier
    // (profile: identifier common to all versions of the report; same source as Composition.identifier in the ELGA maps)
    cda.setId -> fhir_diagnosticReport.identifier "ImagingDiagnosticReportIdentifier";

    // ClinicalDocument/code -> DiagnosticReport.code
    cda.code -> fhir_diagnosticReport.code "ImagingDiagnosticReportCode";

    // DiagnosticReport.category (slice imaging-report, fixed value required by the profile)
    cda ->
        fhir_diagnosticReport.category = create('CodeableConcept') as fhir_category_report,
        fhir_category_report.coding = create('Coding') as fhir_category_report_coding,
        fhir_category_report_coding.system = 'http://loinc.org',
        fhir_category_report_coding.code = '85430-7'
        "ImagingDiagnosticReportCategoryReport";

    // DiagnosticReport.category (slice imaging, fixed value required by the profile)
    cda ->
        fhir_diagnosticReport.category = create('CodeableConcept') as fhir_category_imaging,
        fhir_category_imaging.coding = create('Coding') as fhir_category_imaging_coding,
        fhir_category_imaging_coding.system = 'http://hl7.eu/fhir/health-data-api/CodeSystem/eehrxf-document-priority-category-cs',
        fhir_category_imaging_coding.code = 'Medical-Imaging'
        "ImagingDiagnosticReportCategoryImaging";

    // ClinicalDocument/sdtc:statusCode -> DiagnosticReport.status (case 1: status present in CDA)
    cda.sdtcStatusCode as cda_statusCode then {
        cda_statusCode.code as cda_status_code ->
            fhir_diagnosticReport.status = translate(cda_status_code, '#cda-imaging-sdtc-statuscode-2-fhir-diagnosticreport-status', 'code')
            "ImagingDiagnosticReportStatusMapped";
    } "ImagingDiagnosticReportStatus";

    // DiagnosticReport.status (case 2: no status in CDA -> report is final)
    cda where cda.sdtcStatusCode.exists().not() ->
        fhir_diagnosticReport.status = 'final'
        "ImagingDiagnosticReportStatusFinal";

    // ClinicalDocument/documentationOf/serviceEvent/effectiveTime -> DiagnosticReport.effectivePeriod
    cda.documentationOf first as cda_documentationOf then {
        cda_documentationOf.serviceEvent as cda_serviceEvent then {
            cda_serviceEvent.effectiveTime as cda_serviceEvent_time ->
                fhir_diagnosticReport.effective = create('Period') as fhir_effective_period
                then IVLTSPeriod(cda_serviceEvent_time, fhir_effective_period)
                "ImagingDiagnosticReportEffective";
        } "ImagingServiceEvent";
    } "ImagingDocumentationOf";

    // ClinicalDocument/effectiveTime -> DiagnosticReport.issued
    cda.effectiveTime -> fhir_diagnosticReport.issued "ImagingDiagnosticReportIssued";
}

// ClinicalDocument -> generic header (recordTarget/Patient, author, custodian,
// legalAuthenticator, ...). Reuses CdaHeaderToFhir; imaging report specific header
// mappings (documentationOf/serviceEvent -> Procedure/ImagingStudy timing,
// inFulfillmentOf/order -> ServiceRequest + AccessionNumber)
// will be added here.
group CdaImagingHeaderToFhir(source cda: ClinicalDocument, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_bundle: Bundle, target fhir_diagnosticReport: DiagnosticReport) extends CdaHeaderToFhir {
  // TODO ClinicalDocument/documentationOf/serviceEvent -> Procedure / ImagingStudy
  // TODO ClinicalDocument/inFulfillmentOf/order         -> ServiceRequest (basedOn) + AccessionNumber
  // So basically add every header element here that is not covered in `CdaImagingHeaderToFhirDiagnosticReport` or  `CdaImagingHeaderToFhirComposition`
    // Composition.section:procedure (LOINC 55111-9) with all Procedures
    // The section is created here in the header group (not in the body group) because it is
    // mandatory in the EU profile and its entries (Procedures) come from the header (serviceEvent).
    cda where cda.documentationOf.exists() ->
        fhir_composition.section as fhir_section_procedure,
        fhir_section_procedure.code as fhir_section_procedure_code,
        fhir_section_procedure_code.coding as fhir_section_procedure_coding,
        fhir_section_procedure_coding.system = 'http://loinc.org',
        fhir_section_procedure_coding.code = '55111-9'
    then {
        // Title and text from the CDA section "Durchgefuehrte Untersuchung" (55111-9), if present
        cda.component as cda_component then {
            cda_component.structuredBody as cda_structuredBody then {
                cda_structuredBody.component as cda_body_component then {
                    cda_body_component.section as cda_section where (code.where(code = '55111-9' and codeSystem = '2.16.840.1.113883.6.1'))
                        then CdaSectionToFhirSection(cda_section, fhir_section_procedure, fhir_bundle)
                        "ImagingSectionProcedureText";
                } "ImagingBodyComponent";
            } "ImagingStructuredBody";
        } "ImagingComponent";

        // ClinicalDocument/documentationOf/serviceEvent -> Procedure (ProcedureEuImaging)
        // Each examination (serviceEvent) becomes a separate Procedure in the Bundle
        // and is referenced as an entry in the procedure section.
        cda.documentationOf as cda_documentationOf then {
            cda_documentationOf.serviceEvent as cda_serviceEvent ->
                // create the Procedure and add it to the Bundle
                fhir_bundle.entry as fhir_bundle_entry_procedure,
                fhir_bundle_entry_procedure.resource = create('Procedure') as fhir_procedure,
                fhir_procedure.id = uuid() as fhir_procedure_id,
                fhir_bundle_entry_procedure.fullUrl = append('urn:uuid:', fhir_procedure_id),

                // Procedure.meta.profile
                fhir_procedure.meta as fhir_procedure_meta,
                fhir_procedure_meta.profile = 'http://hl7.eu/fhir/imaging/StructureDefinition/ProcedureEuImaging',

                // Procedure.status: examination is completed (otherwise there would be no report)
                fhir_procedure.status = 'completed',

                // Procedure -> Patient
                fhir_patient.id as fhir_patient_id,
                fhir_procedure.subject = create('Reference') as fhir_procedure_subject_reference,
                fhir_procedure_subject_reference.reference = append('urn:uuid:', fhir_patient_id),
                fhir_procedure_subject_reference.type = 'Patient',

                // procedure section -> Procedure (entry)
                fhir_section_procedure.entry = create('Reference') as fhir_section_procedure_entry,
                fhir_section_procedure_entry.reference = append('urn:uuid:', fhir_procedure_id),
                fhir_section_procedure_entry.type = 'Procedure'

            then {
                // serviceEvent/code -> Procedure.code
                cda_serviceEvent.code -> fhir_procedure.code "ImagingProcedureCode";

                // serviceEvent/effectiveTime -> Procedure.performedPeriod
                cda_serviceEvent.effectiveTime as cda_serviceEvent_time ->
                    fhir_procedure.performed = create('Period') as fhir_procedure_period
                    then IVLTSPeriod(cda_serviceEvent_time, fhir_procedure_period)
                    "ImagingProcedurePerformed";
            } "ImagingServiceEventToProcedure";
        } "ImagingDocumentationOfToProcedure";
    } "ImagingSectionProcedure";
}


// _________________________ Section und Entry Level Templates _________________________

// ClinicalDocument body -> Composition sections. Reuses CdaBodyToFhirComposition, which
// already routes the uncoded sections Brieftext (BRIEFT) and Abschliessende Bemerkungen
// to annotation sections. The imaging section dispatch is added here.
group CdaImagingBodyToFhirComposition(source cda: ClinicalDocument, source cda_structuredBody: StructuredBody, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_diagnosticReport: DiagnosticReport, target fhir_bundle: Bundle) extends CdaBodyToFhirComposition {

    cda_structuredBody.component as cda_component then {

        // Anforderung / order (LOINC 55115-0) -> Composition.section:order (LOINC 55115-0)
        cda_component.section as cda_section where (code.where(code = '55115-0' and codeSystem = '2.16.840.1.113883.6.1')) ->
            fhir_composition.section as fhir_section
            then CdaImagingSectionToFhirSection(cda_section, fhir_section, fhir_bundle)
            "ImagingSectionOrder";

        // Befund / findings (LOINC 18782-3) -> Composition.section:findings (LOINC 59776-5)
        cda_component.section as cda_section where (code.where(code = '18782-3' and codeSystem = '2.16.840.1.113883.6.1')) ->
            fhir_composition.section as fhir_section,
            fhir_section.code as fhir_section_code,
            fhir_section_code.coding as fhir_section_coding,
            fhir_section_coding.system = 'http://loinc.org',
            fhir_section_coding.code = '59776-5'
            then CdaImagingSectionToFhirSection(cda_section, fhir_section, fhir_bundle)
            "ImagingSectionFindings";

        // Verdachtsdiagnose / suspected diagnosis (LOINC 19005-8) -> Composition.section:impression (LOINC 19005-8)
        cda_component.section as cda_section where (code.where(code = '19005-8' and codeSystem = '2.16.840.1.113883.6.1')) ->
            fhir_composition.section as fhir_section
            then CdaImagingSectionToFhirSection(cda_section, fhir_section, fhir_bundle)
            "ImagingSectionImpression";

        // Anamnese / history (LOINC 10164-2) -> Composition.section:history (LOINC 11329-0)
        cda_component.section as cda_section where (code.where(code = '10164-2' and codeSystem = '2.16.840.1.113883.6.1')) ->
            fhir_composition.section as fhir_section,
            fhir_section.code as fhir_section_code,
            fhir_section_code.coding as fhir_section_coding,
            fhir_section_coding.system = 'http://loinc.org',
            fhir_section_coding.code = '11329-0'
            then CdaImagingSectionToFhirSection(cda_section, fhir_section, fhir_bundle)
            "ImagingSectionHistory";

        // Fruehere Untersuchungen und Befunde / prior examinations (LOINC 55114-3) -> Composition.section:comparison (LOINC 18834-2)
        cda_component.section as cda_section where (code.where(code = '55114-3' and codeSystem = '2.16.840.1.113883.6.1')) ->
            fhir_composition.section as fhir_section,
            fhir_section.code as fhir_section_code,
            fhir_section_code.coding as fhir_section_coding,
            fhir_section_coding.system = 'http://loinc.org',
            fhir_section_coding.code = '18834-2'
            then CdaImagingSectionToFhirSection(cda_section, fhir_section, fhir_bundle)
            "ImagingSectionComparison";

        // Weitere empfohlene Massnahmen / recommended actions (LOINC 59772-4) -> Composition.section:recommendation (LOINC 18783-1)
        cda_component.section as cda_section where (code.where(code = '59772-4' and codeSystem = '2.16.840.1.113883.6.1')) ->
            fhir_composition.section as fhir_section,
            fhir_section.code as fhir_section_code,
            fhir_section_code.coding as fhir_section_coding,
            fhir_section_coding.system = 'http://loinc.org',
            fhir_section_coding.code = '18783-1'
            then CdaImagingSectionToFhirSection(cda_section, fhir_section, fhir_bundle)
            "ImagingSectionRecommendation";
    } "ImagingSections";
}

// Common rules for every imaging section.
// Reuses title, text and author from CdaSectionToFhirSection (ELGA) and
// adds the original code of the CDA section.
group CdaImagingSectionToFhirSection(source cda_section: Section, target fhir_section, target fhir_bundle: Bundle) extends CdaSectionToFhirSection {
    // section/code -> Composition.section.code
    // (as an additional coding, so that an EU code set before is kept)
    cda_section.code as cda_section_code ->
        fhir_section.code as fhir_section_code,
        fhir_section_code.coding as fhir_section_coding
        then CDCoding(cda_section_code, fhir_section_coding)
        "ImagingSectionCode";

    // Subsections: section/component/section -> Composition.section.section
    // (calls this group again for every subsection)
    cda_section.component as cda_sub_component then {
        cda_sub_component.section as cda_sub_section ->
            fhir_section.section as fhir_sub_section
            then CdaImagingSectionToFhirSection(cda_sub_section, fhir_sub_section, fhir_bundle)
            "ImagingSubSection";
    } "ImagingSubSections";
}
